"use strict";(globalThis.webpackChunkmy_website||=[]).push([[21996],{11158(a){a.exports=JSON.parse('{"slug":"computation-layer","title":"Computation Layer","short":"An early architectural concept from Cardano\'s original roadmap describing smart contract execution as a layer separate from settlement.","category":"general","aliases":[],"mentalModel":null,"related":["smart-contract","eutxo"],"sources":[],"link":null,"level":"intermediate","body":"An early architectural concept from Cardano\'s original roadmap that imagined two layers: a \\"settlement layer\\" for value transfer and a \\"computation layer\\" for running smart contracts. In practice, smart contract execution was built directly into transaction validation in the eUTXO model rather than existing as a separate layer. The term still appears in older Cardano writing and is kept here for context."}')}}]);